node - <<'JS'
const https=require('https');
const urls=[
'https://www.nasa.gov/mission/gemini-iii/','https://www.nasa.gov/mission/gemini-vi/','https://www.nasa.gov/mission/gemini-vi-a/','https://www.nasa.gov/mission/gemini-ix/','https://www.nasa.gov/mission/gemini-ix-a/'
];
function get(url){return new Promise(resolve=>{https.get(url,res=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>resolve({url,status:res.statusCode,title:(d.match(/<title>(.*?)<\/title>/i)||[])[1]||''}));}).on('error',e=>resolve({url,status:'ERR',title:String(e)}));});}
(async()=>{for(const u of urls){console.log(await get(u));}})();
