python3 - <<'PY'
import requests, subprocess
for code in ['A07','A08','A09']:
    u=f'https://www.nasa.gov/wp-content/uploads/static/apollo50th/pdf/{code}_PressKit.pdf'
    r=requests.get(u,timeout=30)
    print(code,r.status_code,r.headers.get('content-type'))
    if r.status_code==200 and 'pdf' in (r.headers.get('content-type') or ''):
        fn=f'{code}.pdf'; open(fn,'wb').write(r.content)
        print(subprocess.check_output(f"pdftotext {fn} - | grep -n -i 'backup crew' | head -4",shell=True,text=True))
PY

python3 - <<'PY'
import requests,re,html
for m in ['gemini-ix','gemini-x','skylab-2','skylab-3','skylab-4','apollo-7','apollo-8','apollo-9','apollo-10','apollo-11','apollo-12','apollo-13','apollo-14','apollo-15','apollo-16','apollo-17']:
    t=requests.get(f'https://www.nasa.gov/mission/{m}/',timeout=30).text
    print('\n###',m)
    for label in ['Crew','Backup Crew','Launch Pad','Launch','Landing','Duration','Vehicle']:
        for pat in [rf'<p><strong>{re.escape(label)}:?\s*</strong>(.*?)</p>', rf'{re.escape(label)}:?\s*([^<"]+?)<']:
            mm=re.search(pat, t, re.I|re.S)
            if mm:
                val=re.sub('<.*?>','',mm.group(1))
                print(label, html.unescape(' '.join(val.split())))
                break
